import json

def handle_request(request):
    data = json.loads(request)

    order = {
        'name': data['name'],
        'product': data['product'],
        'quantity': int(data['quantity'])
    }

    if order['product'] == 'chocolate bar':
        message = f"Order placed for {order['quantity']} chocolate bars."
    else:
        message = 'Product not available.'

    return message

