import os

def get_file_list(directory):
    dir_list = os.listdir(directory)
    file_list = []

    for i in range(len(dir_list)):
        item_path = os.path.join(directory, dir_list[i])

        if os.path.isfile(item_path):
            file_list.append(dir_list[i])

    return file_list
print(get_file_list('/var/www/html'))

import random

def get_weather(city):
    cities = {
        "New York": (random.randint(-10, 80), "F"),
        "Los Angeles": (random.randint(50, 90), "F"),
        "Chicago": (random.randint(-20, 70), "F")
    }

    weather = cities.get(city)
    if not weather:
        print("Weather information unavailable for this location.")
        return

    temperature, scale = weather

    if scale == "F":
        temperature = (temperature - 32) * 5 / 9
        scale = "C"

    return {"temperature": round(temperature), "scale": scale}

city = input("Enter your city: ")
weather = get_weather(city)

if weather:
    print(f"The current temperature in {city} is {weather['temperature']} {weather['scale']}.")

import jinja2
from flask import request

def render_user_bio(user):
    template = request.args.get('template')
    env = jinja2.Environment(autoescape=False)
    return env.from_string(template).render(bio=user.bio)

